example:
agent Room {
    key id: String
    store conns: Map[String, Connection[Frame]]

    on call fan(text: String) -> Effect[()] {
        conns.parTraverse((c) => c.send(Frame { text: text }))   // ✗ renamed
    }
}

agent Room {
    key id: String
    store conns: Map[String, Connection[Frame]]

    on call fan(text: String) -> Effect[()] {
        conns.parForEach((c) => c.send(Frame { text: text }))    // ✓ runs for effect
    }
}
